package test;

import org.eclipse.jdt.core.ICompilationUnit;
import org.eclipse.jdt.internal.corext.template.java.CompilationUnitContext;
import org.eclipse.jdt.internal.ui.text.template.contentassist.CompilationUnitContextType;
import org.eclipse.jface.text.IDocument;
import org.eclipse.jface.text.templates.TemplateContext;

public class Example {
    public void someMethod(IDocument document, int offset, int length, ICompilationUnit cu, CompilationUnitContextType contextType) {
        CompilationUnitContext context = contextType.createContext(document, offset, length, cu);
        TemplateContext contextGeneric = contextType.createContext(document, offset, length, cu);
        System.out.println(context);
    }
}

