import org.eclipse.jface.text.IDocument;
import org.eclipse.jface.text.templates.TemplateContext;
import org.eclipse.jface.text.templates.TemplateContextType; // A supertype or sibling type

public class NegativeExample {
    public void someMethod(IDocument document, int offset, int length, ICompilationUnit cu, CompilationUnitContextType contextType, TemplateContextType genericContextType) {
        // Rule should not apply here because LHS type is TemplateContext, not CompilationUnitContext
        TemplateContext contextNotMatching = contextType.createContext(document, offset, length, cu);

        // Rule should not apply here because it already has the cast
        CompilationUnitContext contextAlreadyCast = (org.eclipse.jdt.internal.corext.template.java.CompilationUnitContext) contextType.createContext(document, offset, length, cu);

        // Rule should not apply here because the receiver type `genericContextType` does not match the guard for `contextType`
        TemplateContext contextWrongReceiver = genericContextType.createContext(document, offset, length, cu);
    }
}
